create or replace function public.trigger_efact_notification() returns trigger language plpgsql security definer set search_path = public as $$ declare v_customer record; v_garage record; v_lien text; begin if new.einvoice_statut = 'generee' and (old.einvoice_statut is distinct from 'generee' or old.einvoice_statut is null) then select * into v_customer from customers where id = new.customer_id; select * into v_garage from garages where id = new.garage_id; v_lien := 'https://' || coalesce(v_garage.slug, 'rdvrobot.app') || '/verify/' || new.einvoice_numero; insert into notification_queue (garage_id, customer_id, type, canal, payload) values (new.garage_id, new.customer_id, 'efacture_generee', 'whatsapp', jsonb_build_object('client_nom', v_customer.nom, 'facture_num', new.numero, 'efacture_num', new.einvoice_numero, 'montant', new.total, 'devise', v_garage.devise, 'lien_verif', v_lien, 'garage_nom', v_garage.nom)); perform public.audit_write(new.garage_id, 'Notification programmée', new.einvoice_numero); end if; return new; end $$;
create trigger trg_efact_notify after update of einvoice_statut on public.invoices for each row execute function public.trigger_efact_notification();
create or replace function public.fetch_pending_notifications(p_limit int default 50) returns table (id uuid, garage_id uuid, customer_id uuid, type text, canal text, payload jsonb, telephone text) language plpgsql security definer set search_path = public as $$ begin return query select nq.id, nq.garage_id, nq.customer_id, nq.type, nq.canal, nq.payload, c.telephone from notification_queue nq join customers c on c.id = nq.customer_id where nq.statut = 'pending' order by nq.created_at asc limit p_limit; end $$;
create or replace function public.mark_notification_sent(p_id uuid, p_ok boolean, p_ref text default null, p_erreur text default null) returns void language plpgsql security definer set search_path = public as $$ begin update notification_queue set statut = case when p_ok then 'sent' else 'failed' end, sent_at = now(), provider_ref = p_ref, erreur = p_erreur where id = p_id; end $$;
grant execute on function public.fetch_pending_notifications(int) to anon; grant execute on function public.mark_notification_sent(uuid, boolean, text, text) to anon;
